"""Keep palbociclib source grading separate from the platform v5/v6 educational defaults."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[2];p=R/'protocols/breast/00414-palbociclib.json';d=json.loads(p.read_text())
NCCP=d['metadata']['source_url'];NCI='https://dctd.cancer.gov/research/ctep-trials/for-sites/adverse-events/ctcae-v403.pdf'
fields=['anc','platelets','fever_or_infection','prolonged_or_recurrent_grade3','nonhaem_toxicity_grade','nonhaem_persists_despite_treatment']
for field in fields:
 x=d['input_definitions'][field];x.pop('ctcae_version',None)
 if field=='nonhaem_toxicity_grade':x['ctcae_version']='4.0'
 x['grading_source_label']='NCCP 00414 / CTCAE v4.0';x['grading_source_url']=NCI if field=='nonhaem_toxicity_grade' else NCCP;x['ctcae_source_url']=x['grading_source_url'];x['source_grading_note']='NCCP 00414 v5a Tables 2 and 4 cite CTCAE v4.0. Source-specific descriptions and thresholds are retained; no CTCAE v5/v6 automatic grading, substituted descriptors or linked comparison panels are applied.'
d['input_definitions']['anc']['assessment_guidance']='NCCP Table 2: ANC 0.5 to <1.0 ×10⁹/L is grade 3; ANC <0.5 is grade 4. ANC ≥1.0 meets this isolated count criterion only. Grade 3 action depends on Day 1 versus Day 15 of cycles 1–2, fever/infection and recovery. Missing platelets and other domains remain unassessed.'
d['input_definitions']['platelets']['assessment_guidance']='NCCP Table 2: platelets 25 to <50 ×10⁹/L is grade 3; <25 is grade 4. Platelets ≥50 meets this isolated count criterion only. Grade 3 action depends on cycle timing; missing ANC and other domains remain unassessed.'
d['input_definitions']['fever_or_infection']['assessment_guidance']='This is the NCCP Table 2 treatment-modification event: grade 3 neutropenia (ANC 0.5 to <1.0 ×10⁹/L) with fever ≥38.5°C and/or infection. It is not an automatic NCI febrile-neutropenia grade or an emergency-contact threshold; suspected sepsis requires immediate assessment under local policy.'
d['input_definitions']['fever_or_infection']['source_grading_note']+=' The NCCP 38.5°C dose-table condition differs from the NCI CTCAE v4.03 febrile-neutropenia definition; do not relabel the NCCP condition as that CTCAE term.'
d['input_definitions']['prolonged_or_recurrent_grade3']['assessment_guidance']='In NCCP Table 2, grade 3 neutropenia is ANC 0.5 to <1.0 ×10⁹/L. Recovery taking >1 week, or recurrent grade 3 neutropenia on Day 1 of subsequent cycles, prompts consideration of dose reduction; this is clinical event history, not a numeric grade calculator.'
x=d['input_definitions']['nonhaem_toxicity_grade'];x['label']='Non-haematological toxicity grade (NCCP CTCAE v4.0)';x['assessment_guidance']='Document the named adverse event and use its own CTCAE v4.0-series criterion (NCI v4.03 reference). The general severity anchors below are screening aids only; not all grades apply to every event. New pulmonary symptoms / severe ILD use their separate palbociclib rules. This field does not calculate a grade from blood tests.'
descriptions={0:'No non-haematological adverse event reported; this is a no-event option, not a formal CTCAE severity grade.',1:'Generally mild or asymptomatic, with observation alone. Confirm grade 1 against the named CTCAE v4.0-series event; this general anchor is not an event-specific definition.',2:'Generally moderate, requiring limited or non-invasive treatment or affecting instrumental daily activities. Confirm the named event’s CTCAE v4.0-series grade 2 criterion.',3:'Generally severe or medically significant, potentially requiring admission or limiting self-care. Confirm the actual event’s CTCAE v4.0-series grade 3 criterion; a general severity label is insufficient.',4:'Generally life-threatening and requiring urgent intervention. Confirm the named event’s CTCAE v4.0-series grade 4 criterion; some event terms do not have every grade.'}
for o in x['options']:o['description']=descriptions[o['value']]
x['source_grading_note']+=' NCI v4.03 is the published v4.0-series reference (14 June 2010). Its introductory severity anchors do not replace each named adverse-event definition.'
d['input_definitions']['nonhaem_persists_despite_treatment']['assessment_guidance']='Confirm that the already named and graded CTCAE v4.0-series non-haematological event remains grade ≥3 despite medical treatment. This yes/no field records response to treatment; it does not assign a new grade.'
d['ctcae_standard']['reference']='NCCP 00414 v5a cites CTCAE v4.0 in Tables 2 and 4; NCI CTCAE v4.03 is the supporting v4-series reference.'
d['ctcae_standard']['display_requirement']='Numeric/binary fields show the source table guidance without automated v5/v6 grading. The non-haematological selector has explicit general v4-series anchors and requires confirmation against the named adverse-event term.'
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
